'use strict';
// Parse a compact duration string such as "1h30m", "45s" or "2d4h" into
// milliseconds.
const UNITS = { d: 86400000, h: 3600000, m: 60000, s: 1000 };
const ORDER = ['d', 'h', 'm', 's'];
const DURATION_RE = /^\d+[dhms](?:\d+[dhms])*$/;
const GROUP_RE = /(\d+)([dhms])/g;

function parseDuration(input) {
  const str = String(input);
  if (!DURATION_RE.test(str)) {
    throw new RangeError(`invalid duration: ${JSON.stringify(str)}`);
  }

  let total = 0;
  let rank = -1;
  for (const [, amount, unit] of str.matchAll(GROUP_RE)) {
    const position = ORDER.indexOf(unit);
    if (position <= rank) {
      throw new RangeError(`duration units must be unique and largest first: ${JSON.stringify(str)}`);
    }
    rank = position;
    total += Number(amount) * UNITS[unit];
  }
  return total;
}

function formatDuration(ms) {
  let rest = Math.floor(ms);
  const parts = [];
  for (const unit of ORDER) {
    const size = UNITS[unit];
    const n = Math.floor(rest / size);
    rest -= n * size;
    if (n > 0) parts.push(`${n}${unit}`);
  }
  return parts.join('') || '0s';
}

module.exports = { parseDuration, formatDuration };

